CREATE TABLE student_profiles (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, phone text NOT NULL DEFAULT '', department text NOT NULL DEFAULT '', level text NOT NULL DEFAULT '', updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE portal_entries (id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), university_id text REFERENCES universities(id), faculty_id text REFERENCES faculties(id), organization_id text REFERENCES student_organizations(id), department text NOT NULL, kind text NOT NULL CHECK(kind IN ('product','housing','restaurant','ticket','trip','training','team','volunteer','certificate','service','poll')), title text NOT NULL, description text NOT NULL, category text NOT NULL DEFAULT '', image_url text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', price_minor integer NOT NULL DEFAULT 0 CHECK(price_minor >= 0), capacity integer CHECK(capacity >= 0), starts_at timestamp, closes_at timestamp, published boolean NOT NULL DEFAULT false, author_id text NOT NULL REFERENCES "user"(id), created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), FOREIGN KEY (institution_id, university_id) REFERENCES institutions(id, university_id), FOREIGN KEY (faculty_id, university_id) REFERENCES faculties(id, university_id), FOREIGN KEY (organization_id, institution_id, faculty_id, department) REFERENCES student_organizations(id, institution_id, faculty_id, kind));
CREATE INDEX portal_entries_scope_idx ON portal_entries(institution_id,kind,published);
CREATE TABLE portal_requests (id text PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id), entry_id text REFERENCES portal_entries(id), kind text NOT NULL, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewing','accepted','rejected','completed','cancelled')), quantity integer NOT NULL DEFAULT 1 CHECK(quantity BETWEEN 1 AND 99), unit_price_minor integer NOT NULL DEFAULT 0 CHECK(unit_price_minor >= 0), reference text NOT NULL UNIQUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX portal_requests_owner_idx ON portal_requests(user_id,created_at);
CREATE UNIQUE INDEX portal_request_active_entry_idx ON portal_requests(user_id,entry_id) WHERE status IN ('pending','reviewing','accepted');
CREATE TABLE request_messages (id text PRIMARY KEY, request_id text NOT NULL REFERENCES portal_requests(id) ON DELETE CASCADE, author_id text NOT NULL REFERENCES "user"(id), body text NOT NULL, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE portal_saved (id text PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, entry_id text NOT NULL REFERENCES portal_entries(id) ON DELETE CASCADE);
CREATE UNIQUE INDEX portal_saved_unique ON portal_saved(user_id,entry_id);
CREATE TABLE portal_notifications (id text PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, href text NOT NULL, read_at timestamp, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX portal_notifications_owner_idx ON portal_notifications(user_id,created_at);
CREATE TABLE poll_options (id text PRIMARY KEY, entry_id text NOT NULL REFERENCES portal_entries(id) ON DELETE CASCADE, label text NOT NULL, UNIQUE(id,entry_id));
CREATE TABLE poll_votes (id text PRIMARY KEY, entry_id text NOT NULL REFERENCES portal_entries(id), option_id text NOT NULL REFERENCES poll_options(id), user_id text NOT NULL REFERENCES "user"(id), created_at timestamp NOT NULL DEFAULT now(), FOREIGN KEY(option_id,entry_id) REFERENCES poll_options(id,entry_id));
CREATE UNIQUE INDEX poll_one_vote ON poll_votes(entry_id,user_id);
